"""control_figures_pb.json (a number, or null) and control_figures_status.json (why null, what is provisional)."""
from decimal import Decimal
from pathlib import Path
from typing import TYPE_CHECKING

from app.core.figures import KEYS
from app.domain.figures import Determined, Provisional, Unknown
from app.utils.hashing import dumps
from app.utils.money import round_tree
from app.writers.statements import write_text

if TYPE_CHECKING:
    from app.services.run_service import Consolidation

# the brief's appendix: control_figures_<your initials>.json
INITIALS = "pb"


def figure_values(run: "Consolidation") -> dict[str, object]:
    out: dict[str, object] = {}
    for key in KEYS:
        figure = run.figures[key]
        out[key] = None if isinstance(figure, Unknown) else figure.value
    return out


def figure_status(run: "Consolidation") -> dict[str, object]:
    status: dict[str, object] = {}
    for key in KEYS:
        figure = run.figures[key]
        if isinstance(figure, Unknown):
            status[key] = {"status": "unknown", "reason": figure.reason}
        elif isinstance(figure, Provisional):
            status[key] = {"status": "provisional", "open_items": list(figure.open_items)}
        elif isinstance(figure, Determined):
            status[key] = {"status": "determined"}
    causes: dict[str, Decimal] = dict(run.ic.causes) if run.ic else {}
    return {"figures": status, "intercompany_causes": causes, "checks_passed": run.checks_passed,
            "blocked": run.blocked}


def write_control_figures(run: "Consolidation", out: Path) -> None:
    write_text(out / f"control_figures_{INITIALS}.json", dumps(round_tree(figure_values(run))))
    write_text(out / "control_figures_status.json", dumps(round_tree(figure_status(run))))

"""The run registry: one folder per run under .northwind/runs/<id>/ holding its own data, config, outputs and logs.
Config is copied per run so an approval written by one run never changes the repository's overrides.toml."""
import json
import re
import secrets
import shutil
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from app.orchestrator.state import RunState, initial_state
from app.utils.paths import CONFIG_DIR, DEFAULT_DATA_DIR

RUN_ID = re.compile(r"^r\d{8}-\d{6}-[0-9a-f]{4}$")
CONFIG_COPIED = ("policy.toml", "assumptions.toml", "overrides.toml", "bundle_manifest.sha256")


class UnknownRun(Exception):
    pass


class Registry:
    def __init__(self, root: Path) -> None:
        self.root = root

    def folder(self, run_id: str) -> Path:
        """The id is checked against a strict pattern before it touches the file system."""
        if not RUN_ID.match(run_id) or not (self.root / run_id / "run.json").is_file():
            raise UnknownRun(run_id)
        return self.root / run_id

    def data_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "data"

    def config_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "config"

    def out_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "output"

    def meta(self, run_id: str) -> dict[str, Any]:
        return dict(json.loads((self.folder(run_id) / "run.json").read_text(encoding="utf-8")))

    def update(self, run_id: str, **fields: Any) -> dict[str, Any]:
        meta = self.meta(run_id) | fields
        (self.folder(run_id) / "run.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
        return meta

    def create(self, name: str = "", use_sample: bool = False, parent: str | None = None,
               copy_data_from: Path | None = None, copy_config_from: Path = CONFIG_DIR) -> dict[str, Any]:
        stamp = datetime.now(UTC).strftime("%Y%m%d-%H%M%S")
        run_id = f"r{stamp}-{secrets.token_hex(2)}"
        folder = self.root / run_id
        (folder / "data").mkdir(parents=True)
        (folder / "config").mkdir()
        for name_ in CONFIG_COPIED:
            shutil.copy2(copy_config_from / name_, folder / "config" / name_)
        source = copy_data_from or (DEFAULT_DATA_DIR if use_sample else None)
        if source is not None:
            shutil.copytree(source, folder / "data", dirs_exist_ok=True)
        meta: dict[str, Any] = {"id": run_id, "name": name.strip() or run_id, "created": datetime.now(UTC).isoformat(),
                "parent": parent, "status": "new", "open_items": [], "thread": None, "outputs": None}
        (folder / "run.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
        return meta

    def list(self, archived: bool = False) -> list[dict[str, Any]]:
        """Runs in use, or with archived=True the archived ones. Archiving hides a run; nothing is deleted."""
        found = [self.meta(p.name) for p in self.root.glob("r*") if RUN_ID.match(p.name) and (p / "run.json").is_file()]
        shown = [m for m in found if bool(m.get("archived")) == archived]
        return sorted(shown, key=lambda m: str(m["created"]), reverse=True)

    def state(self, run_id: str) -> RunState:
        folder = self.folder(run_id)
        return initial_state(folder / "data", folder / "output", folder / "config", folder / "run.db",
                             folder / "logs")

"""A second implementation of the same method, recomputing the control figures from the raw files.

It shares the policy and the assumptions (A1, A3, A6, A9, and the 2310 remap switch passed in by the run), so it is not
an independent check of the accounting. It imports nothing from app.core or app.parsers (only the figure names and
the invariants): it reads the files itself, works entity by entity in local
currency, and translates once at the end. A disagreement with the pipeline is reported, never adjusted away."""
import csv
import json
import re
from decimal import Decimal as D
from pathlib import Path
from typing import Any

from app.domain.figures import Determined, Figure, Provisional, Unknown
from app.verification.invariants import Check

NUMERIC = ("group_revenue", "group_profit", "profit_owners", "profit_nci", "nci_closing", "goodwill_closing",
           "translation_reserve_movement", "total_assets", "total_equity", "intercompany_difference")
Books = dict[str, D]


def _rows(path: Path) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


class Rates:
    def __init__(self, path: Path) -> None:
        self.value: dict[tuple[str, str, str], D] = {}
        self.window: dict[str, str] = {}
        for r in _rows(path):
            units = r["convention"].split(" per 1 ")[0]
            rate = D(r["rate"]) if units == r["quote_currency"] else 1 / D(r["rate"])
            self.value[(r["base_currency"], r["quote_currency"], r["rate_type"])] = rate
            self.window[r["as_of"]] = r["rate_type"]

    def per_gbp(self, ccy: str, kind: str) -> D:
        usd = self.value[("GBP", "USD", kind)]
        return usd if ccy == "USD" else usd * self.value[("USD", ccy, kind)]


def _add(books: Books, code: str, amount: D) -> None:
    books[code] = books.get(code, D(0)) + amount


def _plus(books: Books, coa: dict[str, dict[str, str]], **match: str) -> D:
    return sum((v for k, v in books.items() if all(coa[k][f] == w for f, w in match.items())), D(0))


def _journals(data: Path, known: dict[str, set[str]], opening: dict[tuple[str, str], D],
              side: dict[tuple[str, str], str]) -> tuple[dict[str, str], list[dict[str, Any]]]:
    """posted, rejected or held for each journal, by rules written afresh here."""
    raw: dict[str, Any] = json.loads(
        (data / "adjustments.json").read_text(encoding="utf-8"), parse_float=str, parse_int=str)
    seen: set[tuple[object, ...]] = set()
    status: dict[str, str] = {}
    balance = dict(opening)
    for e in raw["entries"]:
        lines = [(x["account"], D(x["debit"]), D(x["credit"])) for x in e["lines"]]
        key = (e["entity"], e["date"], tuple(sorted(lines)))
        repeat, unknown, flips = key in seen, any(a not in known[e["entity"]] for a, _, _ in lines), False
        seen.add(key)
        for account, dr, cr in ([] if unknown else lines):
            before = balance.get((e["entity"], account), D(0))
            balance[(e["entity"], account)] = before + dr - cr
            now, normal = before + dr - cr, side.get((e["entity"], account))
            flips = flips or (normal == "Credit" and before <= 0 < now) or (normal == "Debit" and before >= 0 > now)
        bad = sum(x[1] for x in lines) != sum(x[2] for x in lines) or not e["date"].startswith("2024") or repeat
        status[e["id"]] = "rejected" if bad else "held" if unknown or flips else "posted"
    return status, raw["entries"]


def recompute(data: Path, remap_deferred_income: bool = True) -> dict[str, object]:
    rates = Rates(data / "fx_rates.csv")
    coa = {r["account_code"]: r for r in _rows(data / "group_coa.csv")}
    maps = {e: {r["local_code"]: r["group_code"] for r in _rows(data / f"map_{e}.csv")} for e in ("uk", "in")}
    if remap_deferred_income:
        maps["uk"]["2310"] = "2300"
    ents = {r["entity_id"]: r for r in _rows(data / "entities.csv")}
    note = (data / "acquisition_note.md").read_text(encoding="utf-8")

"""Run registry, upload, review and build endpoints. Each calls one existing service."""
from typing import Annotated, Any

from fastapi import APIRouter, Depends, HTTPException, Request

from app.api_models import Decisions, NewRun
from app.services import pipeline_service as pipeline
from app.services.registry_service import Registry
from app.services.upload_service import EXPECTED_FILES, MAX_BYTES, file_status, validate_bytes

router = APIRouter(prefix="/api")


def registry(request: Request) -> Registry:
    reg: Registry = request.app.state.registry
    return reg


Reg = Annotated[Registry, Depends(registry)]


@router.get("/runs")
def list_runs(reg: Reg, archived: bool = False) -> list[dict[str, Any]]:
    return reg.list(archived)


@router.post("/runs/{run_id}/archive")
def archive(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.update(run_id, archived=True)


@router.post("/runs/{run_id}/restore")
def restore(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.update(run_id, archived=False)


@router.post("/runs")
def create_run(body: NewRun, reg: Reg) -> dict[str, Any]:
    return reg.create(body.name, body.use_sample)


@router.get("/runs/{run_id}")
def open_run(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.meta(run_id) | {"files": file_status(reg.data_dir(run_id))}


@router.put("/runs/{run_id}/files/{name}")
async def upload(run_id: str, name: str, request: Request, reg: Reg) -> dict[str, Any]:
    """The body is the raw file. It is checked against its contract in a scratch copy, then stored only if it passes."""
    if name not in EXPECTED_FILES:
        raise HTTPException(422, f"{name} is not one of the 15 expected files")
    folder = reg.data_dir(run_id)
    body = await request.body()
    if len(body) > MAX_BYTES:
        raise HTTPException(413, f"{name} is larger than {MAX_BYTES} bytes")
    error = validate_bytes(name, body)
    if error is None:
        (folder / name).write_bytes(body)
    return {"name": name, "stored": error is None, "error": error}


@router.post("/runs/{run_id}/analyse")
def analyse(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.analyse(reg, run_id)


@router.get("/runs/{run_id}/review")
def review(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.review_view(reg, run_id)


@router.post("/runs/{run_id}/decisions")
def decide(run_id: str, body: Decisions, reg: Reg) -> dict[str, Any]:
    return pipeline.decide(reg, run_id, body.approver, body.decisions)


@router.post("/runs/{run_id}/build")
def build(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.build(reg, run_id)

