"""The model comes from config/llm.toml, or from NORTHWIND_MODEL: a string like ollama:<name> or openai:<name>."""
import importlib
import os
import re
import tomllib
from pathlib import Path
from typing import Any

from pydantic import BaseModel
from pydantic_ai.models import Model, infer_model

from app.llm.ledger import LlmStop
from app.utils.env import load_env
from app.utils.paths import CONFIG_DIR, ROOT


class LlmConfig(BaseModel):
    model: str
    ledger: str
    max_output_tokens: int
    ollama_base_url: str
    request_timeout_s: float = 60
    settings: dict[str, float | int | str] = {}

    @property
    def ledger_path(self) -> Path:
        return ROOT / self.ledger


def ledger_name(model: str) -> str:
    """One ledger file per model, named from the model string, so a cloud run never writes into the local file."""
    return "ledger/" + re.sub(r"[^a-z0-9.]+", "-", model.lower()).strip("-") + ".jsonl"


def load_llm_config(path: Path = CONFIG_DIR / "llm.toml") -> LlmConfig:
    """NORTHWIND_MODEL switches the model and nothing else: the ledger is derived from its name and the sampling
    settings come from the `cloud_settings` table (empty: determinism comes from the ledger, not from a seed)."""
    load_env()
    section = tomllib.loads(path.read_text(encoding="utf-8"))["llm"]
    fields = {k: v for k, v in section.items() if k not in ("settings", "cloud_settings")}
    override = os.environ.get("NORTHWIND_MODEL", "").strip()
    if override and override != section["model"]:
        return LlmConfig(**{**fields, "model": override, "ledger": ledger_name(override)},
                         settings=section.get("cloud_settings", {}))
    return LlmConfig(**fields, settings=section.get("settings", {}))


def model_settings(cfg: LlmConfig) -> dict[str, Any]:
    """Only what config lists is sent (a cloud model may reject temperature or seed), plus the output cap. The
    pydantic-ai OpenAI model sends max_tokens as max_completion_tokens, the name the current API expects."""
    return {"max_tokens": cfg.max_output_tokens, **cfg.settings}


def build_model(cfg: LlmConfig) -> Model:
    provider, _, name = cfg.model.partition(":")
    if provider in ("ollama", "openai"):
        key = os.environ.get("OPENAI_API_KEY", "")
        if provider == "openai" and not key:
            raise LlmStop("OPENAI_API_KEY is not set: paste it into .env (see .env.example) and run again")
        # loaded by name: openai is only in requirements-llm.txt, so a dev-only install must still type-check
        async_openai = importlib.import_module("openai").AsyncOpenAI
        from pydantic_ai.models.openai import OpenAIChatModel
        from pydantic_ai.providers.openai import OpenAIProvider

        if provider == "ollama":
            client = async_openai(base_url=cfg.ollama_base_url, api_key="ollama", timeout=cfg.request_timeout_s)
        else:
            # retries are ours (client.py): the SDK would also retry a 429 that only means "out of credit"
            client = async_openai(api_key=key, timeout=cfg.request_timeout_s, max_retries=0)
        return OpenAIChatModel(name, provider=OpenAIProvider(openai_client=client))
    return infer_model(cfg.model)

"""Grounding: each claim in a verdict is checked on its own against the packet. A claim the packet does not support is
dropped and logged; the others stand. The same exact predicates feed the rule-based fallback."""
import json
import re
from dataclasses import dataclass
from decimal import Decimal
from typing import Any

from app.agents.journal_reviewer.schema import JournalVerdict
from app.agents.mapping_reviewer.schema import MappingVerdictBase
from app.detectors.text_scan import PATTERNS

MIN_SHARED = 2  # a name matches another account only if they share two words: one word ("costs") is not enough


@dataclass(frozen=True)
class Grounded:
    verified: tuple[str, ...]
    dropped: tuple[tuple[str, str], ...]
    unverified: tuple[str, ...] = ()

    @property
    def risk(self) -> bool:
        """Only verified claims count."""
        return bool(self.verified)


def journal_facts(packet: dict[str, Any]) -> dict[str, bool]:
    """What the packet proves, category by category. Wording of free text cannot be proved, so it is not here."""
    start, end = packet["period"]
    lines = packet["lines"]
    flips = False
    for line in lines:
        if line.get("statement") != "BS":
            continue
        before, after = Decimal(line["balance_before"]), Decimal(line["balance_after"])
        flips |= (after > 0 >= before) if line["normal_balance"] == "Credit" else (after < 0 <= before)
    return {
        "unbalanced": packet["total_debit"] != packet["total_credit"],
        "outside_period": not start <= packet["date"] <= end,
        "account_not_in_chart": any(not line["in_entity_chart"] for line in lines),
        "duplicate_of_another": bool(packet["same_lines_as"]),
        "reversal_of_another": bool(packet["mirror_image_of"]),
        "exceeds_balance": flips,
    }


def _texts(packet: dict[str, Any]) -> list[str]:
    quoted = [packet["description"], *(line["memo"] for line in packet["lines"] if line["memo"])]
    return [json.loads(q) for q in quoted]


def ground_journal(verdict: JournalVerdict, packet: dict[str, Any]) -> Grounded:
    facts = journal_facts(packet)
    verified: list[str] = []
    dropped: list[tuple[str, str]] = []
    unverified: list[str] = []
    for flag in verdict.flags:
        if flag == "text_contains_instruction":
            lexicon = any(p.search(t) for t in _texts(packet) for p in PATTERNS)
            (verified if lexicon else unverified).append(flag)
        elif facts[flag]:
            verified.append(flag)
        else:
            dropped.append((flag, f"the supplied data does not support {flag}"))
    return Grounded(tuple(verified), tuple(dropped), tuple(unverified))


def _words(text: str) -> set[str]:
    return {w for w in re.findall(r"[a-z]+", text.lower()) if len(w) > 3}


def mapping_facts(packet: dict[str, Any], coa: dict[str, dict[str, str]]) -> tuple[dict[str, bool], str]:
    """Exact sign test, and the best other group account by shared words with the local name (or "none")."""
    mapped = packet["mapped_to"]
    local = _words(json.loads(packet["local_name"]))
    own = len(local & _words(mapped["name"]))
    best, best_score = "none", max(own, MIN_SHARED - 1)
    for code, account in sorted(coa.items()):
        score = len(local & _words(account["name"]))
        if code != mapped["code"] and score > best_score:
            best, best_score = code, score
    side, normal = packet["balance_side"], mapped["normal_balance"]
    return {
        "sign_unusual": Decimal(packet["balance"]) != 0 and side != normal.lower(),
        "name_mismatch": best != "none",
        "wrong_statement_type": best != "none" and coa[best]["statement"] != mapped["statement"],
    }, best


def _mapping_claim_holds(flag: str, proposed: str, packet: dict[str, Any], coa: dict[str, dict[str, str]]) -> bool:
    mapped = packet["mapped_to"]
    if flag == "sign_unusual":
        return mapping_facts(packet, coa)[0][flag]
    if proposed == "none" or proposed not in coa or proposed == mapped["code"]:
        return False
    if flag == "wrong_statement_type":
        return coa[proposed]["statement"] != mapped["statement"]
    local = _words(json.loads(packet["local_name"]))
    shared = len(local & _words(coa[proposed]["name"]))
    return shared >= MIN_SHARED and shared > len(local & _words(mapped["name"]))


def ground_mapping(verdict: MappingVerdictBase, packet: dict[str, Any], coa: dict[str, dict[str, str]]) -> Grounded:
    proposed = getattr(verdict, "better_group_code", "none")
    verified: list[str] = []
    dropped: list[tuple[str, str]] = []
    for flag in verdict.flags:
        if _mapping_claim_holds(flag, proposed, packet, coa):
            verified.append(flag)
        else:
            dropped.append((flag, f"the supplied data does not support {flag}"))
    return Grounded(tuple(verified), tuple(dropped))

"""What a recorded call cost, from config/pricing.toml. An estimate for the review report: no figure depends on it."""
import tomllib
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path
from typing import Any

from app.utils.paths import CONFIG_DIR

MILLION = Decimal(1_000_000)


def load_prices(path: Path = CONFIG_DIR / "pricing.toml") -> dict[str, dict[str, str]]:
    return tomllib.loads(path.read_text(encoding="utf-8")).get("models", {})


def cost_fields(model: str, usage: dict[str, Any], prices: dict[str, dict[str, str]] | None = None) -> dict[str, Any]:
    """cost_usd as a string (null when the model has no price) and the reason when it is null."""
    price = (prices if prices is not None else load_prices()).get(model)
    if price is None:
        return {"cost_usd": None, "cost_note": f"no price for {model} in config/pricing.toml"}
    cost = (Decimal(usage["input_tokens"]) * Decimal(price["input_per_million"])
            + Decimal(usage["output_tokens"]) * Decimal(price["output_per_million"])) / MILLION
    return {"cost_usd": str(cost.quantize(Decimal("0.000001"))), "cost_note": f"price status {price['status']}"}


@dataclass
class AgentCost:
    calls: int = 0
    input_tokens: int = 0
    output_tokens: int = 0
    recorded_cost: Decimal = Decimal(0)
    new_cost: Decimal = Decimal(0)
    unpriced: int = 0
    new_calls: int = 0


@dataclass
class CostReport:
    per_agent: dict[str, AgentCost] = field(default_factory=dict)

    def total(self) -> AgentCost:
        whole = AgentCost()
        for a in self.per_agent.values():
            whole.calls += a.calls
            whole.new_calls += a.new_calls
            whole.input_tokens += a.input_tokens
            whole.output_tokens += a.output_tokens
            whole.recorded_cost += a.recorded_cost
            whole.new_cost += a.new_cost
            whole.unpriced += a.unpriced
        return whole


def build_report(entries: list[dict[str, Any]], new_keys: set[str]) -> CostReport:
    """The entries a run used. recorded_cost is what they cost when recorded; new_cost is only what this run spent."""
    report = CostReport()
    for entry in entries:
        row = report.per_agent.setdefault(entry["agent"], AgentCost())
        usage = entry.get("usage") or {"input_tokens": 0, "output_tokens": 0}
        row.calls += 1
        row.input_tokens += usage["input_tokens"]
        row.output_tokens += usage["output_tokens"]
        cost = entry["cost_usd"] if "cost_usd" in entry else cost_fields(entry["model"], usage)["cost_usd"]
        if cost is None:
            row.unpriced += entry.get("usage") is not None
            continue
        row.recorded_cost += Decimal(cost)
        if entry["key"] in new_keys:
            row.new_cost += Decimal(cost)
    for entry in entries:
        if entry["key"] in new_keys:
            report.per_agent[entry["agent"]].new_calls += 1
    return report


def format_report(report: CostReport, model: str) -> list[str]:
    lines = [f"cost for {model} (an estimate from config/pricing.toml)"]
    for name, a in [*sorted(report.per_agent.items()), ("all agents", report.total())]:
        unpriced = f", {a.unpriced} calls without a price (cost null)" if a.unpriced else ""
        lines.append(f"  {name}: {a.calls} calls ({a.new_calls} new), {a.input_tokens} input and {a.output_tokens} "
                     f"output tokens, recorded cost ${a.recorded_cost}, new cost this run ${a.new_cost}{unpriced}")
    return lines

"""A per-run limit that counts units sent to a model live (not dollars): replayed answers are free and do not count."""
from dataclasses import dataclass

from app.llm.ledger import Ledger


@dataclass
class UnitBudget:
    limit: int | None = None
    start: set[str] | None = None

    def begin(self, ledger: Ledger) -> "UnitBudget":
        if self.start is None:  # one budget can span the three checkpoints of a run
            self.start = set(ledger.new_keys)
        return self

    def spent(self, ledger: Ledger) -> int:
        return len(ledger.new_keys - (self.start or set()))

    def exhausted(self, ledger: Ledger) -> bool:
        return self.limit is not None and self.spent(ledger) >= self.limit

"""Build the evidence the reasoning checkpoints read from a finished run: the input files, the policy clauses, the
calculation records, the source lines behind each record and the facts the rules already confirm. Nothing here calls a
model; it only turns engine objects into text and numbers."""
import json
import re
from dataclasses import dataclass
from decimal import Decimal
from statistics import median

from app.agents.reasoning.budget import UnitBudget
from app.agents.reasoning.calc_review import CalcReport, review_calculations
from app.agents.reasoning.evidence import Evidence
from app.agents.reasoning.grounding import Grounded
from app.agents.reasoning.investigator import TraceReport, investigate
from app.agents.reasoning.reader import InputReport, read_inputs
from app.agents.reasoning.tools import lineage_text
from app.core.calculations import calculation_records
from app.detectors.mapping import classified, name_nature
from app.detectors.rates import CHECKED_TYPES, percent_apart
from app.domain.calculations import CalcRecord
from app.llm.client import Mode
from app.llm.factory import LlmConfig
from app.llm.ledger import Ledger
from app.services.run_service import Consolidation
from app.utils.money import to_decimal

CLAUSE = re.compile(r"^(\d+)\. ", re.MULTILINE)


def policy_rules(text: str) -> dict[str, str]:
    """`policy N` -> the clause as written, including its indented sub-points."""
    marks = list(CLAUSE.finditer(text))
    ends = [m.start() for m in marks[1:]] + [len(text)]
    return {f"policy {m.group(1)}": text[m.end():end].strip() for m, end in zip(marks, ends, strict=True)}


def _related(run: Consolidation) -> dict[str, str]:
    out: dict[str, list[str]] = {}
    for m in run.mapped:
        if m.group_code is not None:
            line = m.line
            out.setdefault(m.group_code, []).append(
                f"{line.entity} {line.local_code} {line.local_name.quoted()} balance {line.amount} ({line.ref})")
    coa = run.ctx.inputs.coa
    return {code: f"{coa[code].name if code in coa else code}\n" + "\n".join(lines) for code, lines in out.items()}


def _shown(value: Decimal) -> str:
    """Four decimals at most, so a model can quote a number exactly as it is written in the record."""
    return format(value.quantize(Decimal("0.0001")).normalize(), "f")


def record_text(record: CalcRecord) -> str:
    """The record as the model sees it. The full-precision result stays in `Evidence.results` for code."""
    data = record.model_dump(mode="json")
    data["result"] = _shown(record.result)
    for item, original in zip(data["inputs"], record.inputs, strict=True):
        item["value"] = _shown(original.value)
    return json.dumps(data)


def _confirmed(run: Consolidation) -> dict[str, frozenset[str]]:
    """Facts the detectors already proved, by file:line, so a model claim that matches one is verified."""
    nature = {f"{f.file}:{f.line}" for f in run.findings if f.code == "D02" and "nature" in f.key and f.line}
    rates = {f"{f.file}:{f.line}" for f in run.findings if f.code in {"D08", "D15"} and f.file == "fx_rates.csv"
             and f.line}
    return {"nature_mismatch": frozenset(nature), "unit_or_direction_suspect": frozenset(rates)}


def _rate_gaps(run: Consolidation) -> dict[str, Decimal]:
    """The D15 measure for every checked rate row, so a claim about a rate can be tested against it."""
    rows, out = run.ctx.inputs.rates, {}
    for row in rows:
        others = [r.value for r in rows if (r.base, r.quote) == (row.base, row.quote) and r is not row]
        if row.rate_type in CHECKED_TYPES and others:
            out[str(row.ref)] = percent_apart(row.value, median(others))
    return out


def _nature_agrees(run: Consolidation) -> frozenset[str]:
    """Map rows whose name reads as a nature and whose group account has it (the opposite of D02's nature finding)."""
    coa, agree = run.ctx.inputs.coa, set()
    for m in classified(run.ctx):
        nature = name_nature(m.line.local_name.text)
        if m.verdict == "OK" and m.group_code in coa and m.map_ref and nature:
            if coa[m.group_code].account_type == nature[1]:
                agree.add(str(m.map_ref))
    return frozenset(agree)


def build_evidence(run: Consolidation) -> Evidence:
    data_dir = run.ctx.inputs.data_dir
    files = frozenset(p.name for p in data_dir.iterdir() if p.is_file())
    records = calculation_records(run)
    sources = {r.id: "; ".join(i.source for i in r.inputs if not i.source.startswith("calc:")) for r in records}
    return Evidence(
        data_dir=data_dir, files=files, last_year=run.ctx.policy.period.end.year,
        rules=policy_rules((data_dir / "group_policies.md").read_text(encoding="utf-8")),
        calculations={r.id: record_text(r) for r in records},
        results={r.id: r.result if isinstance(r.result, Decimal) else Decimal(str(r.result)) for r in records},
        lineage={rid: lineage_text(data_dir, src, files) for rid, src in sources.items()},
        related=_related(run), confirmed=_confirmed(run), rate_gaps=_rate_gaps(run),
        rate_tolerance=to_decimal(run.ctx.assumptions["rate_neighbour_tolerance_pct"]),
        nature_agrees=_nature_agrees(run),
        normal_sides={r.id: r.normal_side for r in records if r.normal_side},
    )


NOT_AVAILABLE = ("AI review not available: the local model cannot do reliable tool use, so the reasoning layer runs "
                 "on a cloud model only. The rules and every figure are unchanged.")


@dataclass
class ReasoningReport:
    """Advice only. Nothing here is read by the engine, a gate or a writer."""

    available: bool
    note: str = ""
    inputs: InputReport | None = None
    calcs: CalcReport | None = None
    traces: TraceReport | None = None


def run_reasoning(
    run: Consolidation, cfg: LlmConfig, ledger: Ledger, mode: Mode = "replay", model: object | None = None,
    max_units: int | None = None, smoke: bool = False,
) -> ReasoningReport:
    """The three checkpoints in order. `max_units` limits live units for the whole run; `smoke` sends one unit to
    each checkpoint, which is enough to see a provider accept the schema and the tools."""
    if cfg.model.startswith("ollama:") and model is None:
        return ReasoningReport(False, NOT_AVAILABLE)
    evidence = build_evidence(run)
    shared = UnitBudget(max_units)

    def budget() -> UnitBudget:
        return UnitBudget(1) if smoke else shared

    inputs = read_inputs(cfg, ledger, evidence, mode, model, budget())
    calcs = review_calculations(cfg, ledger, evidence, mode, model, budget())
    if smoke and not calcs.concerns() and evidence.calculations:
        first = next(iter(evidence.calculations))
        calcs.findings.append(Grounded(first, "magnitude_implausible", "smoke test of the investigator", "suspicion"))
    traces = investigate(cfg, ledger, evidence, calcs, mode, model, budget())
    return ReasoningReport(True, "", inputs, calcs, traces)

"""Answer a call from the ledger alone."""
from typing import Any, TypeVar

from pydantic import BaseModel, ValidationError

from app.llm.ledger import Ledger, LedgerMiss, RecordedFailure

T = TypeVar("T", bound=BaseModel)


def replay(ledger: Ledger, key: str, schema: type[T]) -> T:
    entry: dict[str, Any] | None = ledger.get(key)
    if entry is None:
        raise LedgerMiss(f"no recorded answer for call {key[:12]} in {ledger.path.name}")
    if not entry["validated"]:
