import re
import sys
import zlib

b = open(sys.argv[1], "rb").read()
for m in re.finditer(rb"stream\r?\n(.*?)\r?\nendstream", b, re.S):
    try:
        d = zlib.decompress(m.group(1))
    except Exception:
        continue
    if b"BT" not in d:
        continue
    for line in d.split(b"\n"):
        if line.rstrip().endswith((b"Tj", b"TJ")):
            print("".join(p.decode("latin-1") for p in re.findall(rb"\((.*?)(?<!\\)\)", line)))
    print("--page--")

