const log=[];
for(let guard=0;guard<40&&left()>0;guard++){
  const fb=[...document.querySelectorAll('button')].find(b=>{const m=b.innerText.match(/(\d+)\/(\d+)/);return m&&+m[1]>0&&/\.(csv|json|md)/.test(b.innerText);});
  if(!fb)break;
  fb.click();await sleep(500);
  const close=[...document.querySelectorAll('button')].find(b=>b.innerText.trim()==='Close'); if(close){close.click();await sleep(300);}
  const row=[...document.querySelectorAll('tr')].find(r=>/\bOpen\b/.test(r.innerText.split('\n').slice(-3).join(' ')));
  if(!row){log.push('no open row in '+fb.innerText.split('\n')[0]);break;}
  row.click();await sleep(700);
  const acks=[...document.querySelectorAll('button')].filter(x=>/Acknowledge/.test(x.innerText));
  if(!acks.length){log.push('no ack in '+fb.innerText.split('\n')[0]+' row '+row.innerText.slice(0,30).replace(/\n/g,' '));break;}
  for(const a of acks){
    const card=a.parentElement.closest('section,article,div[class*=card],div')||document;
    let el=a.parentElement,inp=null;for(let i=0;i<6&&el&&!inp;i++){inp=el.querySelector('input');el=el.parentElement;}
    if(inp)setv(inp,'Priyansh'); a.click();await sleep(700);
  }
  log.push(fb.innerText.split('\n')[0]+' -> left '+left());
}
