import re
from pathlib import Path

root = Path("F:/Integraate_Assignment")
secrets = []
for line in (root / ".env").read_text(encoding="utf-8").splitlines():
    if "=" in line and not line.lstrip().startswith("#"):
        value = line.split("=", 1)[1].strip().strip("\"'")
        if len(value) >= 8:
            secrets.append(value)
generic = [
    re.compile(r"sk-[A-Za-z0-9_\-]{20,}"), re.compile(r"AIza[0-9A-Za-z_\-]{30,}"), re.compile(r"gh[pousr]_[A-Za-z0-9]{30,}"),
    re.compile(r"(?i)bearer\s+[A-Za-z0-9._\-]{20,}"), re.compile(r"(?i)api[_-]?key\"?\s*[:=]\s*\"?[A-Za-z0-9_\-]{24,}"),
    re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----"), re.compile(r"AKIA[0-9A-Z]{16}"),
]
hits = {"env_value": 0}
per = {}
for f in sorted((root / "transcripts").glob("*.jsonl")):
    text = f.read_text(encoding="utf-8", errors="replace")
    for s in secrets:
        if s in text:
            hits["env_value"] += 1
            per.setdefault(f.name, []).append("env value present")
    for i, p in enumerate(generic):
        n = len(p.findall(text))
        if n:
            hits[f"pattern{i}"] = hits.get(f"pattern{i}", 0) + n
            per.setdefault(f.name, []).append(f"pattern{i} x{n}")
print("secret values checked:", len(secrets))
print(hits)
for k, v in list(per.items())[:15]:
    print(k, v)
print("email mentions:", sum(f.read_text(encoding="utf-8", errors="replace").count("[REDACTED_EMAIL]") for f in (root / "transcripts").glob("*.jsonl")))

